    todoStore[nextId] = { id: nextId, text, completed: false };
    nextId++;
  };

  const getTodo = (id: number): { id: number; text: string; completed: boolean } | undefined => todoStore[id];

  const toggleTodo = (id: number) => {
    if (id in todoStore) {
      todoStore[id].completed = !todoStore[id].completed;
    }
  };

  const deleteTodo = (id: number) => {
    delete todoStore[id];
  };

  const listTodos = () => Object.values(todoStore);

  const listCompleted = () => Object.values(todoStore).filter((todo) => todo.completed);

  const listPending = () => Object.values(todoStore).filter((todo) => !todo.completed);

  const clearCompleted = () => {
