let nextId = 1;
const todos: Map<number, Todo> = new Map();

export function createTodoApp(): TodoApp {
  let idCounter = nextId;

  function addTodo(text: string): Todo {
    const todo: Todo = { id: idCounter++, text, completed: false };
    todos.set(todo.id, todo);
    return todo;
  }

  function getTodo(id: number): Todo | undefined {
    return todos.get(id);
  }

  function toggleTodo(id: number): void {
    const todo = todos.get(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  }

  function deleteTodo(id: number): boolean {
    return todos.delete(id);
  }

  function listTodos(): Todo[] {
    return Array.from(todos.values());
  }

  function listCompleted(): Todo[] {
    return Array.from(todos.values()).filter(todo => todo.completed);
  }

  function listPending(): Todo[] {
    return Array.from(todos.values()).filter(todo => !todo.completed);
  }

  function clearCompleted(): void {
    for (const [id, todo] of todos) {
      if (todo.completed) {
        todos.delete(id);
      }
    }
  }

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
}
