  completed: boolean
}

interface TodoApp {
  addTodo(text: string): Todo
  getTodo(id: number): Todo | undefined
  toggleTodo(id: number): void
  deleteTodo(id: number): boolean
  listTodos(): Todo[]
  listCompleted(): Todo[]
  listPending(): Todo[]
  clearCompleted(): void
}

export function createTodoApp(): TodoApp {
  let todos: Todo[] = [];
  let nextId = 1;

  return {
    addTodo(text: string): Todo {
      const newTodo: Todo = {
        id: nextId,
        text: text,
        completed: false
      };
      todos.push(newTodo);
      nextId++;
      return newTodo;
    },

    getTodo(id: number): Todo | undefined {
      return todos.find(todo => todo.id === id);
    },

    toggleTodo(id: number): void {
      const todo = this.getTodo(id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },

    deleteTodo(id: number): boolean {
      const index = todos.findIndex(todo => todo.id === id);
      if (index !== -1) {
        todos.splice(index, 1);
        return true;
      }
      return false;
    },

    listTodos(): Todo[] {
      return [...todos];
    },

    listCompleted(): Todo[] {
      return todos.filter(todo => todo.completed);
    },

    listPending(): Todo[] {
      return todos.filter(todo => !todo.completed);
    },

    clearCompleted(): void {
      todos = todos.filter(todo => !todo.completed);
    }
  };
}
```

---

### ✅ **Key Features**

- **Type Safety**: Uses TypeScript interfaces (`Todo`, `TodoApp`) to ensure type safety.
- **State Management**: Maintains an internal list of todos (`todos`) and tracks the next ID to assign.
- **Immutability**: Uses array methods like `filter` and `splice` to maintain clean and predictable state.
- **Functionality**:
  - `addTodo`: Adds a new todo and returns it.
  - `getTodo`: Retrieves a todo by ID.
  - `toggleTodo`: Toggles the `completed` status of a todo.
  - `deleteTodo`: Removes a todo by ID.
  - `listTodos`, `listCompleted`, `listPending`: Provide views of the todo list.
  - `clearCompleted`: Removes all completed todos.

---

