const todoApp = createTodoApp();

const todo1 = todoApp.addTodo("Buy groceries");
const todo2 = todoApp.addTodo("Read a book");

todoApp.toggleTodo(todo1.id);
todoApp.deleteTodo(todo2.id);

console.log(todoApp.listTodos());
```

This will output:
```typescript
[ { id: 1, text: "Buy groceries", completed: true } ]
```

