interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

interface TodoApp {
  addTodo(text: string): Todo;
  getTodo(id: number): Todo | undefined;
  toggleTodo(id: number): void;
  deleteTodo(id: number): boolean;
  listTodos(): Todo[];
  listCompleted(): Todo[];
  listPending(): Todo[];
  clearCompleted(): void;
}

export function createTodoApp(): TodoApp {
  let nextId = 1;
  const todosMap = new Map<number, Todo>();

  const addTodo = (text) => {
    const newTodo = { id: nextId, text, completed: false };
    todosMap.set(nextId, newTodo);
    nextId++;
    return newTodo;
  };

  const getTodo = (id) => todosMap.get(id);

  const toggleTodo = (id) => {
    const todo = todosMap.get(id);
    if (todo) todo.completed = !todo.completed;
  };

  const deleteTodo = (id) => {
    return todosMap.has(id) ? todosMap.delete(id) : false;
  };

  const listTodos = () => Array.from(todosMap.values());

  const listCompleted = () => listTodos().filter((t) => t.completed);

  const listPending = () => listTodos().filter((t) => !t.completed);

  const clearCompleted = () => {
    const newMap = new Map<number, Todo>();
    for (const [id, todo] of todosMap) {
      if (!todo.completed) newMap.set(id, todo);
    }
    todosMap = newMap;
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}
