const createTodoApp = () => {
  let todos: { id: number; text: string; completed: boolean }[] = [];
  let nextId = 1;
  let deletedIds: number[] = [];

  const addTodo = (text: string) => {
    const id = deletedIds.length > 0 ? deletedIds.shift()! : nextId++;
    todos.push({ id, text, completed: false });
    return id;
  };

  const getTodo = (id: number) => {
    return todos.find(todo => todo.id === id) || null;
  };

  const toggleTodo = (id: number) => {
    const todo = getTodo(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number) => {
    const index = todos.findIndex(todo => todo.id === id);
    if (index !== -1) {
      todos.splice(index, 1);
      deletedIds.push(id);
      deletedIds.sort((a, b) => a - b);
    }
  };

  const listTodos = () => {
    return [...todos];
  };

  const listCompleted = () => {
    return todos.filter(todo => todo.completed);
  };

  const listPending = () => {
    return todos.filter(todo => !todo.completed);
  };

  const clearCompleted = () => {
    todos = todos.filter(todo => !todo.completed);
    // Reset deletedIds since we're not reusing IDs of completed todos
    deletedIds = [];
    // Rebuild nextId based on current todos
    nextId = todos.length > 0 ? Math.max(...todos.map(t => t.id)) + 1 : 1;
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
};
