interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

const idCounter = 1;

function createTodoApp(): {
  addTodo: (text: string) => Todo;
  getTodo: (id: number) => Todo | undefined;
  toggleTodo: (id: number) => void;
  deleteTodo: (id: number) => void;
  listTodos: () => Todo[];
  listCompleted: () => Todo[];
  listPending: () => Todo[];
  clearCompleted: () => void;
} {
  const todos: Todo[] = [];
  const ids: Set<number> = new Set();

  function addTodo(text: string): Todo {
    const id = idCounter++;
    const newTodo: Todo = { id, text, completed: false };
    todos.push(newTodo);
    ids.add(id);
    return newTodo;
  }

  function getTodo(id: number): Todo | undefined {
    return todos.find(t => t.id === id);
  }

  function toggleTodo(id: number): void {
    const todo = todos.find(t => t.id === id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  }

  function deleteTodo(id: number): void {
    const index = todos.indexOf(id);
    if (index !== -1) {
      todos.splice(index, 1);
      ids.delete(id);
    }
  }

  function listTodos(): Todo[] {
    return todos;
  }

  function listCompleted(): Todo[] {
    return todos.filter(t => t.completed);
  }

  function listPending(): Todo[] {
    return todos.filter(t => !t.completed);
  }

  function clearCompleted(): void {
    const newTodos = todos.filter(t => !t.completed);
    const newIds = new Set(ids);
    for (const todo of todos) {
      if (todo.completed) {
        newIds.delete(todo.id);
      }
    }
    todos = newTodos;
    ids = newIds;
  }

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted
  };
}
