interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

interface TodoApp {
  addTodo(text: string): void;
  getTodo(id: number): Todo | undefined;
  toggleTodo(id: number): void;
  deleteTodo(id: number): void;
  listTodos(): Todo[];
  listCompleted(): Todo[];
  listPending(): Todo[];
  clearCompleted(): void;
}

export function createTodoApp(): TodoApp {
  let nextId = 1;
  const store = new Map<number, Todo>();

  return {
    addTodo(text) {
      if (typeof text !== "string") {
        throw new Error("text must be a string");
      }
      const todo: Todo = { id: nextId++, text, completed: false };
      store.set(todo.id, todo);
    },

    getTodo(id) {
      return store.get(id);
    },

    toggleTodo(id) {
      const todo = store.get(id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },

    deleteTodo(id) {
      store.delete(id);
    },

    listTodos() {
      return Array.from(store.values());
    },

    listCompleted() {
      return store
        .values()
        .filter((t: Todo) => t.completed) as Array<Todo>;
    },

    listPending() {
      return store
        .values()
        .filter((t: Todo) => !t.completed) as Array<Todo>;
    },

    clearCompleted() {
      for (const todo of store.values()) {
        if (todo.completed) {
          store.delete(todo.id);
        }
      }
    },
  };
}
