export const createTodoApp = (() => {
  let nextId = 1;
  const todos: { id: number; text: string; completed: boolean }[] = [];

  const addTodo = (text: string): void => {
    const todo = { id: nextId++, text, completed: false };
    todos.push(todo);
  };

  const getTodo = (id: number): { id: number; text: string; completed: boolean } | undefined =>
    todos.find((t) => t.id === id);

  const toggleTodo = (id: number): void => {
    const todo = getTodo(id);
    if (todo) todo.completed = !todo.completed;
  };

  const deleteTodo = (id: number): void => {
    const index = todos.findIndex((t) => t.id === id);
    if (index !== -1) todos.splice(index, 1);
  };

  const listTodos = (): typeof todos => [...todos];

  const listCompleted = (): typeof todos => todos.filter((t) => t.completed);

  const listPending = (): typeof todos => todos.filter((t) => !t.completed);

  const clearCompleted = (): void => {
    todos.splice(0, todos.length, ...todos.filter((t) => !t.completed));
  };

  return { addTodo, getTodo, toggleTodo, deleteTodo, listTodos, listCompleted, listPending, clearCompleted };
})();
