type Todo = {
  id: number;
  text: string;
  completed: boolean;
};

type TodoApp = {
  addTodo: (text: string) => Todo;
  getTodo: (id: number) => Todo | undefined;
  toggleTodo: (id: number) => boolean;
  deleteTodo: (id: number) => boolean;
  listTodos: () => Todo[];
  listCompleted: () => Todo[];
  listPending: () => Todo[];
  clearCompleted: () => void;
};

function createTodoApp(): TodoApp {
  let todos: Todo[] = [];
  let nextId = 1;

  return {
    addTodo(text: string): Todo {
      const todo: Todo = {
        id: nextId++,
        text,
        completed: false,
      };
      todos.push(todo);
      return todo;
    },

    getTodo(id: number): Todo | undefined {
      return todos.find(t => t.id === id);
    },

    toggleTodo(id: number): boolean {
      const todo = todos.find(t => t.id === id);
      if (todo) {
        todo.completed = !todo.completed;
        return true;
      }
      return false;
    },

    deleteTodo(id: number): boolean {
      const index = todos.findIndex(t => t.id === id);
      if (index !== -1) {
        todos.splice(index, 1);
        return true;
      }
      return false;
    },

    listTodos(): Todo[] {
      return [...todos];
    },

    listCompleted(): Todo[] {
      return todos.filter(t => t.completed);
    },

    listPending(): Todo[] {
      return todos.filter(t => !t.completed);
    },

    clearCompleted(): void {
      todos = todos.filter(t => !t.completed);
    },
  };
}

export { createTodoApp, type Todo, type TodoApp };
