let nextId = 1;
const todos: Record<number, Todo> = {};

export function createTodoApp(): TodoApp {
  const app: TodoApp = {
    addTodo(text) {
      const todo = { id: nextId++, text, completed: false };
      todos[todo.id] = todo;
      return todo;
    },
    getTodo(id) {
      return todos[id];
    },
    toggleTodo(id) {
      if (todos[id]) {
        todos[id].completed = !todos[id].completed;
      }
    },
    deleteTodo(id): boolean {
      if (todos[id]) {
        delete todos[id];
        return true;
      }
      return false;
    },
    listTodos() {
      return Object.values(todos);
    },
    listCompleted() {
      return Object.values(todos).filter(todo => todo.completed);
    },
    listPending() {
      return Object.values(todos).filter(todo => !todo.completed);
    },
    clearCompleted(): void {
      Object.entries(todos).forEach(([id]) => {
        if (todos[id] && todos[id].completed) {
          delete todos[id];
        }
      });
    },
  };
  return app;
}

