This implementation:

1. Uses a factory function pattern with `createCalculator()` returning a new calculator instance
2. Maintains separate state for current value and memory
3. Returns the calculator instance from all methods for chaining
4. Implements all required operations with proper typing
5. Keeps memory operations independent from current value
6. Returns the correct types for all methods
7. Uses TypeScript's type inference for return types

```ts
interface Calculator {
  add(n: number): Calculator;
  subtract(n: number): Calculator;
  multiply(n: number): Calculator;
  divide(n: number): Calculator;
  clear(): Calculator;
  result(): number;
  memoryStore(): Calculator;
  memoryRecall(): number;
  memoryClear(): Calculator;
  memoryAdd(): Calculator;
}

export function createCalculator(): Calculator {
  return new CalculatorImpl();
}

class CalculatorImpl {
  private value: number = 0;
  private memory: number = 0;

  add(n: number): this {
    this.value += n;
    return this;
  }

  subtract(n: number): this {
    this.value -= n;
    return this;
  }

  multiply(n: number): this {
    this.value *= n;
    return this;
  }

  divide(n: number): this {
    if (n === 0) {
      throw new Error("Division by zero");
    }
    this.value /= n;
    return this;
  }

  clear(): this {
    this.value = 0;
    return this;
  }

  result(): number {
    return this.value;
  }

  memoryStore(): this {
    this.memory = this.value;
    return this;
  }

  memoryRecall(): number {
    return this.memory;
  }

  memoryClear(): this {
    this.memory = 0;
    return this;
  }

  memoryAdd(): this {
    this.memory += this.value;
    return this;
  }
