class CalculatorImpl implements Calculator {
  private currentValue: number = 0;
  private memoryValue: number = 0;

  add(n: number): CalculatorImpl {
    this.currentValue += n;
    return this;
  }

  subtract(n: number): CalculatorImpl {
    this.currentValue -= n;
    return this;
  }

  multiply(n: number): CalculatorImpl {
    this.currentValue *= n;
    return this;
  }

  divide(n: number): CalculatorImpl {
    if (n === 0) {
      throw new Error("Division by zero is not allowed");
    }
    this.currentValue /= n;
    return this;
  }

  clear(): CalculatorImpl {
    this.currentValue = 0;
    return this;
  }

  result(): number {
    return this.currentValue;
  }

  memoryStore(): CalculatorImpl {
    this.memoryValue = this.currentValue;
    return this;
  }

  memoryRecall(): number {
    this.currentValue = this.memoryValue;
    return this.currentValue;
  }

  memoryClear(): CalculatorImpl {
    this.currentValue = 0; // Updates current value, not memory
    return this;
  }

  memoryAdd(): CalculatorImpl {
    this.currentValue += this.memoryValue;
    return this;
  }
}

export function createCalculator(): Calculator {
  return new CalculatorImpl();
