export function createCalculator() {
  let current = 0;   // current value of the calculator
  let memory = 0;    // stored memory value

  const calculator = {
    /** Add a number to the current value */
    add(n: number) {
      current += n;
      return calculator;
    },

    /** Subtract a number from the current value */
    subtract(n: number) {
      current -= n;
      return calculator;
    },

    /** Multiply the current value by a number */
    multiply(n: number) {
      current *= n;
      return calculator;
    },

    /** Divide the current value by a number (NaN on divide‑by‑zero) */
    divide(n: number) {
      current = n === 0 ? NaN : current / n;
      return calculator;
    },

    /** Reset the current value to 0 */
    clear() {
      current = 0;
      return calculator;
    },

    /** Return the current value (does not alter state) */
    result() {
      return current;
    },

    /** Store the current value into memory */
    memoryStore() {
      memory = current;
      return calculator;
    },

    /** Add the current value to the stored memory */
    memoryAdd() {
      memory += current;
      return calculator;
    },

    /** Clear the stored memory */
    memoryClear() {
      memory = 0;
      return calculator;
    },

    /** Return the stored memory value (does not alter state) */
    memoryRecall() {
      return memory;
    },
  };

  return calculator;
}
