    todos.filter((t) => t.completed);

  const listPending = (): Todo[] =>
    todos.filter((t) => !t.completed);

  const clearCompleted = (): void => {
    for (let i = todos.length - 1; i >= 0; i--) {
      if (todos[i].completed) todos.splice(i, 1);
    }
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
