export function createTodoApp(): TodoApp {
  // Internal storage for todos using a Map for efficient look‑ups
  const todos = new Map<number, Todo>();
  // Auto‑incrementing id counter – values are never reused
  let nextId = 1;

  return {
    addTodo(text: string) {
      const todo: Todo = { id: nextId++, text, completed: false };
      todos.set(todo.id, todo);
      return todo;
    },

    getTodo(id: number) {
      return todos.get(id);
    },

    toggleTodo(id: number) {
      const todo = todos.get(id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },

    deleteTodo(id: number) {
      return todos.delete(id);
    },

    listTodos() {
      return Array.from(todos.values());
    },

    listCompleted() {
      return Array.from(todos.values()).filter(t => t.completed);
    },

    listPending() {
      return Array.from(todos.values()).filter(t => !t.completed);
    },

    clearCompleted() {
      for (const [id, todo] of todos.entries()) {
        if (todo.completed) {
          todos.delete(id);
        }
      }
    }
  };
}

