  // Arithmetic operations (chainable)
  add(value: number): this;
  subtract(value: number): this;
  multiply(value: number): this;
  divide(value: number): this;
  clear(): this;

  // Query current result
  result(): number;

  // Memory operations (chainable)
  memoryStore(): this;
  memoryAdd(): this;
  memoryClear(): this;

  // Query current memory value (non‑chainable)
  memoryRecall(): number;
}

/**
 * Factory function that creates a new calculator instance.
 *
 * @returns {Calculator} The calculator object with all methods.
 */
export function createCalculator(): Calculator {
  let currentValue = 0;
  let memoryValue = 0;

  const calculator: Calculator = {
    add(n: number) {
      currentValue += n;
      return this;
    },
    subtract(n: number) {
      currentValue -= n;
      return this;
    },
    multiply(n: number) {
      currentValue *= n;
      return this;
    },
    divide(n: number) {
      currentValue /= n;
      return this;
    },
    clear() {
      currentValue = 0;
      return this;
    },

    result() {
      return currentValue;
    },

    memoryStore() {
      memoryValue = currentValue;
      return this;
    },
    memoryAdd() {
      memoryValue += currentValue;
      return this;
    },
    memoryClear() {
      memoryValue = 0;
      return this;
    },

