export function createTodoApp() {
  type Todo = {
    id: number;
    text: string;
    completed: boolean;
  };

  const todos: Todo[] = [];
  let nextId = 1;

  const addTodo = (text: string): Todo => {
    const todo: Todo = { id: nextId++, text, completed: false };
    todos.push(todo);
    return { ...todo };
  };

  const getTodo = (id: number): Todo | undefined => {
    const t = todos.find((t) => t.id === id);
    return t ? { ...t } : undefined;
  };

  const toggleTodo = (id: number): void => {
    const t = todos.find((t) => t.id === id);
    if (t) t.completed = !t.completed;
  };

  const deleteTodo = (id: number): void => {
    const idx = todos.findIndex((t) => t.id === id);
    if (idx !== -1) todos.splice(idx, 1);
  };

  const listTodos = (): Todo[] => todos.map((t) => ({ ...t }));

  const listCompleted = (): Todo[] =>
    todos.filter((t) => t.completed).map((t) => ({ ...t }));

  const listPending = (): Todo[] =>
    todos.filter((t) => !t.completed).map((t) => ({ ...t }));

  const clearCompleted = (): void => {
    let idx = 0;
    while (idx < todos.length) {
      if (todos[idx].completed) {
        todos.splice(idx, 1);
      } else {
        idx++;
      }
    }
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}
