export interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

let todoCounter = 0;
const todos: Todo[] = [];

function generateId(): number {
  return ++todoCounter;
}

export function createTodoApp() {
  const addTodo = (text: string): Todo => {
    if (!text.trim()) {
      throw new Error('Todo text cannot be empty');
    }
    const newTodo: Todo = { id: generateId(), text: text, completed: false };
    todos.push(newTodo);
    return newTodo;
  };

  const getTodo = (id: number): Todo | undefined => {
    return todos.find((todo) => todo.id === id);
  };

  const toggleTodo = (id: number): void => {
    const todo = getTodo(id);
    if (todo !== undefined) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): void => {
    const index = todos.findIndex((todo) => todo.id === id);
    if (index !== -1) {
      todos.splice(index, 1);
    }
  };

  const listTodos = (): Todo[] => {
    return [...todos];
  };

  const listCompleted = (): Todo[] => {
    return [...todos].filter((todo) => todo.completed);
  };

  const listPending = (): Todo[] => {
    return [...todos].filter((todo) => !todo.completed);
  };

  const clearCompleted = (): void => {
    const initialLength = todos.length;
    let deleted = 0;
    let currentIndex = 0;
    while (currentIndex < initialLength) {
      if (todos[currentIndex].completed) {
        todos.splice(currentIndex, 1);
        deleted++;
      } else {
        currentIndex++;
      }
    }
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}
