        if (entry.completed) {
          result.push({ ...entry });
        }
      }
      return result;
    },

    listPending() {
      const result: { id: number; text: string; completed: boolean }[] = [];
      for (const [_, entry] of todoMap.entries()) {
        if (!entry.completed) {
          result.push({ ...entry });
        }
      }
      return result;
    },

    clearCompleted() {
      for (const [key, value] of todoMap.entries()) {
        if (value.completed) {
          todoMap.delete(key);
        }
      }
    },
  };
}

export { createTodoApp };
