 * This is a simple Todo application that allows adding, retrieving, toggling, and deleting todos,
 * as well as listing all todos and completed/pending todos.
 */

interface Todo {
  id: number;
  text: string;
  completed: boolean;
}

let todoId = 1;

const todos: Todo[] = [];

function createTodoApp() {
  return {
    addTodo(text: string): void {
      todos.push({ id: todoId++, text, completed: false });
    },

    getTodo(id: number): Todo | undefined {
      return todos.find(todo => todo.id === id);
    },

    toggleTodo(id: number): void {
      const todo = todos.find(todo => todo.id === id);
      if (todo) {
        todo.completed = !todo.completed;
      }
    },

    deleteTodo(id: number): void {
      todos.filter(todo => todo.id !== id);
    },

    listTodos(): Todo[] {
      return todos.map(todo => ({ ...todo }));
    },

    listCompleted(): Todo[] {
      return todos.filter(todo => todo.completed).map(todo => ({ ...todo }));
    },

    listPending(): Todo[] {
      return todos.filter(todo => !todo.completed).map(todo => ({ ...todo }));
    },

    clearCompleted(): void {
      todos.forEach((_, index, arr) => {
        if (arr[index].completed) {
          delete arr[index];
        }
      });
      todoId = 1;
      todos.sort((a, b) => a.id - b.id);
    },
  };
}

