    divide(value: number) {
      if (value === 0) {
        throw new Error('Division by zero');
      }
      currentValue /= value;
      return calc;
    },
    clear() {
      currentValue = 0;
      return calc;
    },
    result() {
      return currentValue;
    },

    memoryStore() {
      memoryValue = currentValue;
      return calc;
    },
    memoryAdd() {
      memoryValue += currentValue;
      return calc;
    },
