// TodoApp Module

export function createTodoApp() {
  // Todo data structure
  type Todo = { id: number; text: string; completed: boolean };

  // In‑memory storage
  const todos: Todo[] = [];
  let nextId = 1; // auto‑incrementing, never reused

  /**
   * Adds a new todo.
   * @param text the todo text
   * @returns the created todo
   */
  function addTodo(text: string): Todo {
    const todo: Todo = { id: nextId++, text, completed: false };
    todos.push(todo);
    return todo;
  }

  /**
   * Retrieves a todo by ID.
   * @param id the todo id
   * @returns the todo or undefined if not found
   */
  function getTodo(id: number): Todo | undefined {
    return todos.find((t) => t.id === id);
  }

  /**
   * Toggles the completed status of a todo.
   * @param id the todo id
   * @returns true if toggled, false if not found
   */
  function toggleTodo(id: number): boolean {
    const todo = todos.find((t) => t.id === id);
    if (!todo) return false;
    todo.completed = !todo.completed;
    return true;
  }

  /**
   * Deletes a todo by ID.
   * @param id the todo id
   * @returns true if deleted, false if not found
   */
  function deleteTodo(id: number): boolean {
    const idx = todos.findIndex((t) => t.id === id);
    if (idx === -1) return false;
    todos.splice(idx, 1);
    return true;
  }

  /**
   * Lists all todos.
   * @returns a new array of all todos
   */
  function listTodos(): Todo[] {
    return [...todos];
  }

  /**
   * Lists all completed todos.
   * @returns a new array of completed todos
   */
  function listCompleted(): Todo[] {
    return todos.filter((t) => t.completed);
  }

  /**
   * Lists all pending todos.
   * @returns a new array of pending todos
   */
  function listPending(): Todo[] {
    return todos.filter((t) => !t.completed);
  }

  /**
   * Clears all completed todos.
   */
  function clearCompleted(): void {
    // Update the array to only keep pending todos
    const pending = todos.filter((t) => !t.completed);
    todos.splice(0, todos.length, ...pending);
  }

  // Expose the API
  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}
