  addTodo(text: string): Todo;
  getTodo(id: number): Todo | undefined;
  toggleTodo(id: number): void;
  deleteTodo(id: number): boolean;
  listTodos(): Todo[];
  listCompleted(): Todo[];
  listPending(): Todo[];
  clearCompleted(): void;
}

export function createTodoApp(): TodoApp {
  let nextId = 1;
  const todos: Todo[] = [];

  const addTodo = (text: string): Todo => {
    const todo: Todo = { id: nextId++, text, completed: false };
    todos.push(todo);
    return todo;
  };

  const getTodo = (id: number): Todo | undefined => {
    return todos.find(t => t.id === id);
  };

  const toggleTodo = (id: number): void => {
    const todo = getTodo(id);
    if (todo) {
      todo.completed = !todo.completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    const index = todos.findIndex(t => t.id === id);
    if (index !== -1) {
      todos.splice(index, 1);
      return true;
    }
    return false;
  };

  const listTodos = (): Todo[] => {
    return [...todos];
  };

  const listCompleted = (): Todo[] => {
    return todos.filter(t => t.completed);
  };

  const listPending = (): Todo[] => {
    return todos.filter(t => !t.completed);
  };

  const clearCompleted = (): void => {
    for (let i = todos.length - 1; i >= 0; i--) {
      if (todos[i].completed) {
        todos.splice(i, 1);
      }
    }
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
